package com.adc.domain.performance;

import com.adc.domain.shared.BusinessValues;
import java.math.*;
import java.time.*;
import java.util.*;

/** Frozen R1 inputs; no database, current clock, authorization, or generated version in this calculation. */
public final class QuarterlyCalculation {
    private QuarterlyCalculation(){}
    public record Dentist(long id,String hire,String termination){}
    public record Assignment(long id,long dentist,long clinic,String start,String end,boolean active){}
    public record Schedule(long id,long dentist,long clinic,String date,String start,String end,String status){}
    public record Revenue(long item,long invoice,long applied,long dentist,long clinic,String issued,String amount,boolean consistent){}
    public record Cost(long id,Long dentist,long clinic,String type,String amount,String incurred,String source,String batch,String description,Long reversal,boolean consistent){}
    public record Closure(long clinic,String source,String verification,List<String> zeroScopes){}
    public record Input(String rule,String start,String end,String cutoff,List<Long> clinics,List<Dentist> personnel,List<Assignment> assignments,List<Schedule> schedules,List<Revenue> revenue,List<Cost> costs,List<Closure> closures,String personnelReference,String preparer){}
    public record Amounts(String revenue,String medical,String operating,String profit,String incentive){}
    public record Calculation(Map<Long,Amounts> people,List<String> reasons,List<Map<String,Object>> allocations){}
    private static final BigDecimal ZERO=new BigDecimal("0.00");
    private static BigDecimal amount(String text){return BusinessValues.money(text);}
    private static boolean includes(String start,String end,String day){return start.compareTo(day)<=0 && (end==null || end.compareTo(day)>=0);}
    public static Calculation calculate(Input input){
        if(!"R1".equals(input.rule))throw new IllegalArgumentException("Unsupported rule");var reasons=new TreeSet<String>();var personnel=new TreeMap<Long,Dentist>();for(var dentist:input.personnel)if(personnel.put(dentist.id,dentist)!=null)throw new IllegalArgumentException("Duplicate personnel");
        var revenues=new TreeMap<Long,BigDecimal>();var medical=new TreeMap<Long,BigDecimal>();var operating=new TreeMap<Long,BigDecimal>();for(long id:personnel.keySet()){revenues.put(id,ZERO);medical.put(id,ZERO);operating.put(id,ZERO);}var invoiceItems=new HashSet<Long>();
        for(var row:input.revenue){if(!invoiceItems.add(row.item) || !row.consistent || !personnel.containsKey(row.dentist))reasons.add("INCONSISTENT_REVENUE_SOURCE:"+row.item);else revenues.merge(row.dentist,amount(row.amount),BigDecimal::add);}
        if(input.personnelReference==null || input.personnelReference.isBlank())reasons.add("MISSING_PERSONNEL_VERIFICATION");
        for(long clinic:input.clinics){var closures=input.closures.stream().filter(c->c.clinic==clinic).toList();if(closures.size()!=1 || closures.getFirst().source==null || closures.getFirst().source.isBlank() || closures.getFirst().verification==null || closures.getFirst().verification.isBlank()){reasons.add("MISSING_CLOSURE:"+clinic);continue;}var closure=closures.getFirst();for(String type:List.of("MEDICAL_SUPPLY","OPERATING")){var facts=input.costs.stream().filter(c->c.clinic==clinic && c.type.equals(type)).toList();boolean positiveOrReversal=facts.stream().anyMatch(c->amount(c.amount).signum()!=0);if(!positiveOrReversal && (!closure.zeroScopes.contains(type) || facts.stream().noneMatch(c->amount(c.amount).signum()==0 && c.description!=null && !c.description.isBlank())))reasons.add("MISSING_ZERO_COST_SCOPE:"+clinic+":"+type);}}
        var publicCosts=new TreeMap<Long,List<Cost>>();for(var cost:input.costs){if(!cost.consistent){reasons.add("INVALID_COST_SOURCE:"+cost.id);continue;}if(cost.type.equals("MEDICAL_SUPPLY") && cost.dentist==null){reasons.add("MISSING_MEDICAL_DENTIST:"+cost.id);continue;}if(cost.dentist!=null){if(!personnel.containsKey(cost.dentist)){reasons.add("MISSING_COST_PERSONNEL:"+cost.id);continue;}(cost.type.equals("MEDICAL_SUPPLY")?medical:operating).merge(cost.dentist,amount(cost.amount),BigDecimal::add);}else if(cost.type.equals("OPERATING"))publicCosts.computeIfAbsent(cost.clinic,k->new ArrayList<>()).add(cost);else reasons.add("INVALID_COST_TYPE:"+cost.id);}
        var allocations=new ArrayList<Map<String,Object>>();for(var pool:publicCosts.entrySet()){
            var minutes=new TreeMap<Long,Long>();for(long id:personnel.keySet())minutes.put(id,0L);for(var schedule:input.schedules){var dentist=personnel.get(schedule.dentist);if(schedule.clinic!=pool.getKey() || !schedule.status.equals("NORMAL") || dentist==null || schedule.date.compareTo(input.start)<0 || schedule.date.compareTo(input.end)>=0 || !includes(dentist.hire,dentist.termination,schedule.date))continue;boolean assigned=input.assignments.stream().anyMatch(a->a.active && a.dentist==schedule.dentist && a.clinic==schedule.clinic && includes(a.start,a.end,schedule.date));if(assigned){long duration=Duration.between(LocalTime.parse(schedule.start),LocalTime.parse(schedule.end)).toMinutes();if(duration<=0)throw new IllegalArgumentException("Invalid schedule duration");minutes.merge(schedule.dentist,duration,Math::addExact);}}
            var sources=pool.getValue().stream().sorted(Comparator.comparingLong(Cost::id)).toList();var net=sources.stream().map(c->amount(c.amount)).reduce(ZERO,BigDecimal::add);if(minutes.values().stream().allMatch(m->m==0) && net.signum()!=0){reasons.add("MISSING_NORMAL_MINUTES:"+pool.getKey());continue;}if(minutes.values().stream().allMatch(m->m==0) && net.signum()==0){allocations.add(Map.of("clinic_id",Long.toString(pool.getKey()),"net_amount","0.00","recipients",minutes.keySet().stream().map(id->Map.of("dentist_id",Long.toString(id),"normal_minutes","0","share","0.00")).toList(),"voucher_reconciliation",sources.stream().map(c->Map.of("cost_entry_id",Long.toString(c.id),"amount",c.amount)).toList(),"method","ZERO_NET_NO_ALLOCATION_REQUIRED"));continue;}var shares=QuarterlyPerformanceRules.allocate(net,minutes);for(var share:shares.entrySet())operating.merge(share.getKey(),share.getValue(),BigDecimal::add);
            // A deterministic reconciliation bridge decomposes the final net allocation by source.
            // Only final net shares enter profit; the bridge is evidence, never a second expense.
            var bridge=new ArrayList<Map<String,Object>>();var previous=new TreeMap<Long,BigDecimal>();for(long id:minutes.keySet())previous.put(id,ZERO);var running=ZERO;for(var cost:sources){running=running.add(amount(cost.amount));Map<Long,BigDecimal> cumulative;if(minutes.values().stream().allMatch(m->m==0)){cumulative=new TreeMap<>();minutes.keySet().forEach(id->cumulative.put(id,ZERO));}else cumulative=QuarterlyPerformanceRules.allocate(running,minutes);var contributions=new TreeMap<String,String>();for(long id:minutes.keySet())contributions.put(Long.toString(id),cumulative.get(id).subtract(previous.get(id)).toPlainString());if(minutes.values().stream().anyMatch(m->m>0) && contributions.values().stream().map(BigDecimal::new).reduce(ZERO,BigDecimal::add).compareTo(amount(cost.amount))!=0)throw new IllegalStateException("Voucher bridge is not conserved");bridge.add(Map.of("cost_entry_id",Long.toString(cost.id),"amount",cost.amount,"net_allocation_bridge",contributions));previous=new TreeMap<>(cumulative);}
            var recipients=new ArrayList<Map<String,Object>>();for(long id:minutes.keySet())recipients.add(Map.of("dentist_id",Long.toString(id),"normal_minutes",Long.toString(minutes.get(id)),"share",shares.get(id).toPlainString()));allocations.add(Map.of("clinic_id",Long.toString(pool.getKey()),"net_amount",net.toPlainString(),"recipients",recipients,"voucher_reconciliation",bridge,"method","R1_NET_LARGEST_REMAINDER"));
        }
        var people=new TreeMap<Long,Amounts>();for(long id:personnel.keySet()){if(!reasons.isEmpty()){people.put(id,new Amounts(null,null,null,null,null));continue;}var revenue=amount(revenues.get(id).toPlainString());var med=amount(medical.get(id).toPlainString());var op=amount(operating.get(id).toPlainString());var net=amount(revenue.subtract(med).subtract(op).toPlainString());people.put(id,new Amounts(revenue.toPlainString(),med.toPlainString(),op.toPlainString(),net.toPlainString(),QuarterlyPerformanceRules.incentive(net).toPlainString()));}return new Calculation(Collections.unmodifiableMap(people),List.copyOf(reasons),List.copyOf(allocations));
    }
}
